import pathlib
p = pathlib.Path("src/codegen/lower_inst/method_resolution.rs")
s = p.read_text()
old = '''    // A call that cannot THROW contributes no frame to anyone's trace, and recording one would do
    // worse than waste work: the buffer holds one trace at a time, so `$e->getTraceAsString()` —
    // itself a call into a builtin class — replaced the frames it was being asked to render with a
    // frame for the question.
    if !ctx.is_main || !inst.effects.contains(crate::ir::Effects::MAY_THROW) {
        return;
    }
    let Some((frame_name, arguments)) = internal_call_frame_shape(ctx, inst, class_name) else {
        return;
    };'''
new = '''    if !ctx.is_main {
        return;
    }
    let Some((frame_name, arguments)) = internal_call_frame_shape(ctx, inst, class_name) else {
        return;
    };'''
assert s.count(old) == 1
s = s.replace(old, new)

old = '''        crate::ir::Op::MethodCall | crate::ir::Op::NullsafeMethodCall => {
            let method = method_name_data(ctx, inst).ok()?;'''
new = '''        crate::ir::Op::MethodCall | crate::ir::Op::NullsafeMethodCall => {
            let method = method_name_data(ctx, inst).ok()?;
            // ASKING an exception about itself is not a frame in anyone's trace. The buffer holds
            // one trace at a time, so recording here replaced the frames `getTraceAsString()` was
            // being asked to render with a frame for the question — and left them replaced for
            // whatever was reported next.
            if super::throwable_methods::is_throwable_standard_method_key(&php_symbol_key(method)) {
                return None;
            }'''
assert s.count(old) == 1
s = s.replace(old, new)
p.write_text(s)
print("intrinsics excluded")
